$ErrorActionPreference = 'Stop'
$workspace = (Resolve-Path -LiteralPath $PSScriptRoot).Path
$stage = Join-Path $workspace '.scratch/architecture-refactor-2026-10-18/cuda-native-storage-cast/cleanup'
$plan = Get-Content -LiteralPath (Join-Path $stage 'plan.json') -Raw | ConvertFrom-Json
$scratch = Join-Path $workspace '.scratch'
foreach ($entry in $plan.protected) {
  $actual = Get-Item -LiteralPath $entry.path
  if ($actual.Length -ne $entry.bytes -or (Get-FileHash -LiteralPath $actual.FullName -Algorithm SHA256).Hash -ne $entry.sha256) { throw "Protected identity mismatch: $($entry.path)" }
}
foreach ($entry in $plan.targets) {
  $actual = Get-Item -LiteralPath $entry.path
  $inside = $false
  foreach ($prefix in $plan.allowed_directories) {
    if ($actual.FullName.StartsWith($prefix + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { $inside = $true }
  }
  if ($plan.allowed_exact -contains $actual.FullName) { $inside = $true }
  if (-not $actual.FullName.StartsWith($scratch + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase) -or -not $inside -or $actual.PSIsContainer -or ($actual.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Unsafe exact target: $($entry.path)" }
  if ($actual.Extension -notin @('.map','.lib','.exp','.exe') -or $actual.Length -ne $entry.bytes -or (Get-FileHash -LiteralPath $actual.FullName -Algorithm SHA256).Hash -ne $entry.sha256) { throw "Target identity mismatch: $($entry.path)" }
  if ($plan.protected.path -contains $actual.FullName) { throw "Protected deletion target: $($actual.FullName)" }
}
$removed = @()
foreach ($entry in $plan.targets) { Remove-Item -LiteralPath $entry.path; $removed += $entry }
foreach ($entry in $plan.protected) {
  $actual = Get-Item -LiteralPath $entry.path
  if ($actual.Length -ne $entry.bytes -or (Get-FileHash -LiteralPath $actual.FullName -Algorithm SHA256).Hash -ne $entry.sha256) { throw "Protected changed: $($entry.path)" }
}
@{ executed = $true; utc = [DateTime]::UtcNow.ToString('o'); files = $removed.Count; bytes = ($removed | Measure-Object -Property bytes -Sum).Sum; removed = $removed } | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $stage 'executed.json') -Encoding utf8
Write-Output "Removed $($removed.Count) exact generated files; reclaimed $($plan.bytes) bytes."
